3	import React, { useEffect, useState } from 'react';
4	import { useRouter } from 'next/navigation';
5	import { useAuth } from '@/context/AuthContext';
6	import { useLanguage } from './lib/i18n';
7	import { databases, storage } from '@/lib/appwrite';
8	import { BUCKET_ID, DB_ID, TABLE_ID, getErrorMessage, normalizePublicUrl } from '@/lib/app-config';
9	import { ID, Permission, Role } from 'appwrite';
10	import {
11	  Smartphone,
12	  Globe,
13	  Sparkles,
14	  Loader2,
15	  CheckCircle2,
16	  AlertCircle,
17	  Eye,
18	  RefreshCw,
19	  ExternalLink,
20	  Check,
21	  HelpCircle,
22	  ShieldCheck,
23	  Zap,
24	  Layers3,
25	  Bell,
26	  Send,
27	  Play,
28	  ArrowUpRight,
29	} from 'lucide-react';
30	
31	export default function HomePage() {
32	  const router = useRouter();
33	  const { user, openAuthModal } = useAuth();
34	  const { lang } = useLanguage();
35	
36	  const [storeUrl, setStoreUrl] = useState('');
37	  const [appName, setAppName] = useState('');
38	  const [platform, setPlatform] = useState<'both' | 'android' | 'ios'>('both');
39	  const [themeColor, setThemeColor] = useState('#6366f1');
40	  const [iconFile, setIconFile] = useState<File | null>(null);
41	  const [iconPreview, setIconPreview] = useState('');
42	  const [admobAppId, setAdmobAppId] = useState('');
43	  const [admobBannerUnitId, setAdmobBannerUnitId] = useState('');
44	  const [iframeKey, setIframeKey] = useState(0);
45	  const [notificationTitle, setNotificationTitle] = useState('عرض خاص من متجرك');
46	  const [notificationMessage, setNotificationMessage] = useState('خصم 50% لفترة محدودة على جميع المنتجات!');
47	  const [previewNotification, setPreviewNotification] = useState(false);
48	  const [previewNotificationKey, setPreviewNotificationKey] = useState(0);
49	
50	  const [loading, setLoading] = useState(false);
51	  const [statusMsg, setStatusMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
52	
53	  const isRtl = lang === 'ar';
54	  const notificationDefaults = lang === 'ar'
55	    ? {
56	        title: 'عرض خاص من متجرك',
57	        message: 'خصم 50% لفترة محدودة على جميع المنتجات!',
58	        fallbackTitle: 'عرض خاص',
59	        fallbackMessage: 'رسالة تجريبية لمتجرك',
60	        now: 'الآن · تجربة Appifya',
61	      }
62	    : lang === 'fr'
63	      ? {
64	          title: 'Offre spéciale de votre boutique',
65	          message: '50 % de réduction pendant une durée limitée sur tous les produits !',
66	          fallbackTitle: 'Offre spéciale',
67	          fallbackMessage: 'Message de test pour votre boutique',
68	          now: 'Maintenant · Démo Appifya',
69	        }
70	      : {
71	          title: 'Special offer from your store',
72	          message: '50% off for a limited time on all products!',
73	          fallbackTitle: 'Special offer',
74	          fallbackMessage: 'A test message for your store',
75	          now: 'Now · Appifya demo',
76	        };
77	
78	  useEffect(() => {
79	    const defaultTitles = ['عرض خاص من متجرك', 'Special offer from your store', 'Offre spéciale de votre boutique'];
80	    const defaultMessages = [
81	      'خصم 50% لفترة محدودة على جميع المنتجات!',
82	      '50% off for a limited time on all products!',
83	      '50 % de réduction pendant une durée limitée sur tous les produits !',
84	    ];
85	
86	    if (defaultTitles.includes(notificationTitle)) {
87	      // Keep untouched sample content aligned with the selected language.
88	      // eslint-disable-next-line react-hooks/set-state-in-effect
89	      setNotificationTitle(notificationDefaults.title);
90	    }
91	    if (defaultMessages.includes(notificationMessage)) {
92	      // eslint-disable-next-line react-hooks/set-state-in-effect
93	      setNotificationMessage(notificationDefaults.message);
94	    }
95	  }, [lang, notificationDefaults.message, notificationDefaults.title, notificationMessage, notificationTitle]);
96	
97	  const handleUrlChange = (val: string) => {
98	    setStoreUrl(val);
99	    if (!appName && val) {
100	      try {
101	        const clean = val.replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[/?#]/)[0];
102	        const namePart = clean.split('.')[0];
103	        if (namePart) {
104	          setAppName(namePart.charAt(0).toUpperCase() + namePart.slice(1));
105	        }
106	      } catch {}
107	    }
108	  };
109	
110	  const getCleanPreviewUrl = () => {
111	    if (!storeUrl) return '';
112	    if (storeUrl.startsWith('http://') || storeUrl.startsWith('https://')) {
113	      return storeUrl;
114	    }
115	    return `https://${storeUrl}`;
116	  };
117	
118	  const executeSaveApp = async (userId: string) => {
119	    if (!storeUrl) {
120	      setStatusMsg({
121	        type: 'error',
122	        text: lang === 'ar' ? 'يرجى إدخال رابط المتجر أولاً.' : lang === 'fr' ? 'Veuillez saisir l\'URL de la boutique.' : 'Please enter your store URL first.',
123	      });
124	      return;
125	    }
126	
127	    try {
128	      setLoading(true);
129	      setStatusMsg(null);
130	
131	      let formattedUrl: string;
132	      try {
133	        formattedUrl = normalizePublicUrl(storeUrl.trim());
134	      } catch {
135	        setStatusMsg({
136	          type: 'error',
137	          text: lang === 'ar' ? 'يرجى إدخال رابط HTTPS صالح.' : lang === 'fr' ? 'Veuillez saisir une URL HTTPS valide.' : 'Please enter a valid HTTPS URL.',
138	        });
139	        return;
140	      }
141	      const finalAppName = appName.trim() || 'My PWA Store';
142	      const normalizedAppId = admobAppId.trim();
143	      const normalizedBannerUnitId = admobBannerUnitId.trim();
144	
145	      if (normalizedAppId && !/^ca-app-pub-\d{10,}~\d{8,}$/.test(normalizedAppId)) {
146	        setStatusMsg({
147	          type: 'error',
148	          text: lang === 'ar' ? 'معرّف تطبيق AdMob غير صالح. يجب أن يكون بصيغة ca-app-pub-...~...' : lang === 'fr' ? 'L’identifiant d’application AdMob doit respecter le format ca-app-pub-...~... .' : 'The AdMob App ID must use the ca-app-pub-...~... format.',
149	        });
150	        return;
151	      }
152	
153	      if (normalizedBannerUnitId && !/^ca-app-pub-\d{10,}\/\d{6,}$/.test(normalizedBannerUnitId)) {
154	        setStatusMsg({
155	          type: 'error',
156	          text: lang === 'ar' ? 'معرّف إعلان Banner غير صالح. يجب أن يكون بصيغة ca-app-pub-.../... .' : lang === 'fr' ? 'L’identifiant Banner doit respecter le format ca-app-pub-.../... .' : 'The banner ad unit ID must use the ca-app-pub-.../... format.',
157	        });
158	        return;
159	      }
160	
161	      let iconId: string | undefined;
162	      if (iconFile) {
163	        if (!BUCKET_ID) {
164	          throw new Error('Appwrite Storage is not configured.');
165	        }
166	
167	        const uploadedIcon = await storage.createFile({
168	          bucketId: BUCKET_ID,
169	          fileId: ID.unique(),
170	          file: iconFile,
171	          permissions: [Permission.read(Role.any())],
172	        });
173	        iconId = uploadedIcon.$id;
174	      }
175	
176	      await databases.createDocument(DB_ID, TABLE_ID, ID.unique(), {
177	        user_id: userId,
178	        store_url: formattedUrl,
179	        app_name: finalAppName,
180	        theme_color: themeColor,
181	        icon_id: iconId,
182	        admob_app_id: normalizedAppId || undefined,
183	        admob_banner_unit_id: normalizedBannerUnitId || undefined,
184	      });
185	
186	      setStatusMsg({
187	        type: 'success',
188	        text: lang === 'ar' ? 'تم حفظ التطبيق وتصديره بنجاح! جاري تحويلك إلى لوحة التحكم...' : lang === 'fr' ? 'Application enregistrée avec succès ! Redirection...' : 'Application saved successfully! Redirecting to your dashboard...',
189	      });
190	
191	      setTimeout(() => {
192	        router.push('/dashboard');
193	      }, 1000);
194	    } catch (err: unknown) {
195	      console.error(err);
196	      setStatusMsg({
197	        type: 'error',
198	        text: getErrorMessage(err, lang === 'ar' ? 'فشل حفظ التطبيق، يرجى المحاولة ثانية.' : lang === 'fr' ? 'Échec de l’enregistrement de l’application.' : 'Failed to save the application.'),
199	      });
200	    } finally {
201	      setLoading(false);
202	    }
203	  };
204	
205	  const handleIconChange = (file: File | undefined) => {
206	    if (!file) return;
207	    if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type) || file.size > 2 * 1024 * 1024) {
208	      setStatusMsg({
209	        type: 'error',
210	        text: lang === 'ar' ? 'اختر صورة PNG أو JPG أو WebP بحجم أقصى 2MB.' : lang === 'fr' ? 'Choisissez une image PNG, JPG ou WebP de 2 Mo maximum.' : 'Choose a PNG, JPG, or WebP image up to 2MB.',
211	      });
212	      return;
213	    }
214	    setIconFile(file);
215	    setIconPreview(URL.createObjectURL(file));
216	  };
217	
218	  const handleCreateOrExport = () => {
219	    if (!storeUrl) {
220	      setStatusMsg({
221	        type: 'error',
222	        text: lang === 'ar' ? 'يرجى إدخال رابط المتجر أولاً.' : lang === 'fr' ? 'Veuillez saisir l\'URL de la boutique.' : 'Please enter your store URL first.',
223	      });
224	      return;
225	    }
226	
227	    if (!user) {
228	      openAuthModal(() => {
229	        if (typeof window !== 'undefined') {
230	          window.location.reload();
231	        }
232	      });
233	      return;
234	    }
235	
236	    executeSaveApp(user.$id);
237	  };
238	
239	  const simulateNotification = () => {
240	    setPreviewNotificationKey((current) => current + 1);
241	    setPreviewNotification(true);
242	    if ('vibrate' in navigator) {
243	      navigator.vibrate([120, 70, 120]);
244	    }
245	  };
246	
247	  return (
248	    <main className="site-main flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 py-8 sm:py-12" dir={isRtl ? 'rtl' : 'ltr'}>
249	      <div className="text-center max-w-3xl mx-auto mb-10">
250	        <h1 className="text-3xl sm:text-5xl font-black text-white tracking-tight leading-tight mb-4">
251	          {lang === 'ar' ? (
252	            <>حوّل متجرك أو صفحة الهبوط إلى <span className="bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-500 bg-clip-text text-transparent">تطبيق PWA فائق السرعة</span></>
253	          ) : lang === 'fr' ? (
254	            <>Transformez votre boutique en une <span className="bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-500 bg-clip-text text-transparent">PWA Mobile Ultra-Rapide</span></>
255	          ) : (
256	            <>Convert Your Store or Landing Page into a <span className="bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-500 bg-clip-text text-transparent">Fast Mobile PWA</span></>
257	          )}
258	        </h1>
259	        <p className="text-sm sm:text-base text-slate-400 leading-relaxed max-w-2xl mx-auto">
260	          {lang === 'ar'
261	            ? 'أنشئ تطبيق ويب تقدمي قابل للتثبيت بضغطة زر، مدمج بحزم إعلانية متوافقة ومربوط سحابياً مع لوحة تحكمك.'
262	            : lang === 'fr'
263	              ? 'Créez une Progressive Web App installable en un clic, personnalisable et synchronisée avec le cloud.'
264	              : 'Build an installable Progressive Web App in one click, customize it, and keep it synced with your cloud dashboard.'}
265	        </p>
266	      </div>
267	
268	      <section className="showcase-panel relative isolate mb-12 overflow-hidden rounded-[2rem] border border-indigo-500/20 bg-gradient-to-br from-indigo-950 via-slate-950 to-pink-950 p-5 shadow-2xl shadow-indigo-950/30 sm:p-8" aria-labelledby="showcase-title">
269	        <div className="pointer-events-none absolute -left-20 -top-24 -z-10 h-64 w-64 rounded-full bg-indigo-500/20 blur-3xl" />
270	        <div className="pointer-events-none absolute -bottom-24 -right-16 -z-10 h-64 w-64 rounded-full bg-pink-500/15 blur-3xl" />
271	        <div className="grid items-center gap-8 lg:grid-cols-[1.05fr_0.95fr]">
272	          <div className={isRtl ? 'text-right' : 'text-left'}>
273	            <div className="mb-4 inline-flex items-center gap-2 rounded-full border border-indigo-300/20 bg-white/5 px-3 py-1.5 text-[11px] font-bold text-indigo-200">
274	              <Sparkles className="h-3.5 w-3.5" />
275	              {lang === 'ar' ? 'شاهد كيف تتحول فكرتك إلى تطبيق' : lang === 'fr' ? 'Voyez votre idée devenir une application' : 'See your idea become an app'}
276	            </div>
277	            <h2 id="showcase-title" className="max-w-xl text-2xl font-black leading-tight text-white sm:text-4xl">
278	              {lang === 'ar' ? 'تجربة عصرية تبدأ من رابط واحد' : lang === 'fr' ? 'Une expérience moderne à partir d’un seul lien' : 'A modern experience from one simple link'}
279	            </h2>
280	            <p className="mt-4 max-w-xl text-sm leading-7 text-slate-300">
281	              {lang === 'ar'
282	                ? 'أدخل رابط متجرك، خصص مظهر التطبيق، ثم شاهد المعاينة الفورية قبل النشر. كل خطوة واضحة ومصممة لتكسب ثقة زوارك.'
283	                : lang === 'fr'
284	                  ? 'Ajoutez votre lien, personnalisez l’apparence et prévisualisez votre application avant de la publier.'
285	                  : 'Add your store link, customize the look, and preview your app before publishing. Every step is clear and built to earn trust.'}
286	            </p>
287	            <div className="mt-6 flex flex-wrap gap-3">
288	              <a href="#builder" className="inline-flex items-center gap-2 rounded-xl bg-white px-4 py-2.5 text-xs font-bold text-indigo-950 shadow-lg transition hover:bg-indigo-50">
289	                <Play className="h-3.5 w-3.5 fill-current" />
290	                {lang === 'ar' ? 'ابدأ التجربة' : lang === 'fr' ? 'Commencer' : 'Start building'}
291	              </a>
292	              <a href="/about" className="inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/5 px-4 py-2.5 text-xs font-bold text-white transition hover:bg-white/10">
293	                {lang === 'ar' ? 'اكتشف الطريقة' : lang === 'fr' ? 'Découvrir' : 'Discover how it works'}
294	                <ArrowUpRight className="h-3.5 w-3.5" />
295	              </a>
296	            </div>
297	          </div>
298	
299	          <div className="relative mx-auto w-full max-w-md">
300	            <div className="showcase-window overflow-hidden rounded-2xl border border-white/15 bg-slate-900/80 shadow-2xl backdrop-blur">
301	              <div className="flex items-center gap-1.5 border-b border-white/10 px-4 py-3">
302	                <span className="h-2.5 w-2.5 rounded-full bg-red-400" />
303	                <span className="h-2.5 w-2.5 rounded-full bg-amber-300" />
304	                <span className="h-2.5 w-2.5 rounded-full bg-emerald-400" />
305	                <span className="ml-2 truncate rounded-md bg-white/5 px-3 py-1 text-[9px] text-slate-400">appifya.app/preview</span>
306	              </div>
307	              <div className="relative aspect-[16/10] overflow-hidden">
308	                <img src="/logo.jpg.jpeg" alt="Appifya platform preview" className="h-full w-full object-cover opacity-35" />
309	                <div className="absolute inset-0 bg-gradient-to-tr from-indigo-950/95 via-indigo-950/40 to-transparent" />
310	                <div className="absolute inset-x-5 bottom-5">
311	                  <div className="mb-3 h-2 w-20 rounded-full bg-indigo-300/60" />
312	                  <div className="h-3 w-4/5 rounded-full bg-white/80" />
313	                  <div className="mt-2 h-2 w-3/5 rounded-full bg-white/30" />
314	                  <div className="mt-5 flex gap-2">
315	                    <span className="h-7 w-20 rounded-lg bg-white/90" />
316	                    <span className="h-7 w-14 rounded-lg bg-white/20" />
317	                  </div>
318	                </div>
319	              </div>
320	            </div>
321	            <div className="showcase-step absolute -bottom-4 -left-3 rounded-xl border border-indigo-300/20 bg-slate-900/95 px-3 py-2 shadow-xl sm:-left-6">
322	              <div className="flex items-center gap-2">
323	                <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-emerald-400/15 text-emerald-300"><Check className="h-4 w-4" /></span>
324	                <span className="text-[10px] font-bold text-white">{lang === 'ar' ? 'جاهز للنشر' : lang === 'fr' ? 'Prêt à publier' : 'Ready to publish'}</span>
325	              </div>
326	            </div>
327	          </div>
328	        </div>
329	      </section>
330	
331	      {statusMsg && (
332	        <div
333	          className={`max-w-4xl mx-auto mb-8 p-4 rounded-2xl border flex items-center gap-3 text-sm font-medium ${
334	            statusMsg.type === 'success'
335	              ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-300'
336	              : 'bg-red-500/10 border-red-500/30 text-red-300'
337	          }`}
338	        >
339	          {statusMsg.type === 'success' ? <CheckCircle2 className="h-5 w-5 shrink-0" /> : <AlertCircle className="h-5 w-5 shrink-0" />}
340	          <span>{statusMsg.text}</span>
341	        </div>
342	      )}
343	
344	      <div id="builder" className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
345	        {/* Mockup Preview */}
346	        <div className="lg:col-span-5 flex flex-col items-center order-2 lg:order-1">
347	          <div className="sticky top-24 w-full max-w-[340px]">
348	            <div className="flex items-center justify-between mb-3 px-2">
349	              <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-slate-900 border border-slate-800 text-[11px] font-semibold text-indigo-400 rounded-full">
350	                <Eye className="h-3.5 w-3.5" />
351	                <span>{lang === 'ar' ? 'معاينة حية للمتجر' : lang === 'fr' ? 'Aperçu interactif direct' : 'Live store preview'}</span>
352	              </span>
353	              {storeUrl && (
354	                <div className="flex items-center gap-1">
355	                  <button
356	                    type="button"
357	                    onClick={() => setIframeKey((k) => k + 1)}
358	                    className="p-1 text-slate-400 hover:text-white rounded-lg hover:bg-slate-900 transition-colors"
359	                    title={lang === 'ar' ? 'تحديث المعاينة' : lang === 'fr' ? 'Actualiser l’aperçu' : 'Refresh preview'}
360	                  >
361	                    <RefreshCw className="h-3.5 w-3.5" />
362	                  </button>
363	                  <a
364	                    href={getCleanPreviewUrl()}
365	                    target="_blank"
366	                    rel="noopener noreferrer"
367	                    className="inline-flex items-center gap-1 rounded-lg bg-slate-900 px-2 py-1 text-[10px] font-semibold text-indigo-300 hover:bg-slate-800 hover:text-white transition-colors"
368	                  >
369	                    <ExternalLink className="h-3 w-3" />
370	                    <span>{lang === 'ar' ? 'فتح خارجياً' : lang === 'fr' ? 'Ouvrir' : 'Open externally'}</span>
371	                  </a>
