'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useLanguage } from '../lib/i18n';
import {
  Smartphone,
  Download,
  ShieldCheck,
  Settings,
  CheckCircle2,
  AlertTriangle,
  Chrome,
  Share2,
  PlusSquare,
  LayoutDashboard,
  ChevronDown,
} from 'lucide-react';

// ---------------------------------------------------------------------------
// Inline SVG illustrations — Appifya brand colours (indigo / pink / slate)
// ---------------------------------------------------------------------------

function IllustrationDownload() {
  return (
